<?php
namespace App\Services;use App\Models\Customer;use Illuminate\Support\Collection;
class CustomerDedupService {public function findPossibleDuplicates(string $name,?string $phone,?string $address):Collection{$m=collect();if($phone){$n=Customer::normalizePhone($phone);Customer::whereHas('contacts',fn($q)=>$q->whereIn('type',['phone','whatsapp'])->where('value',$n))->get()->each(fn($c)=>$m->put($c->id,['customer'=>$c,'reason'=>'Nomor kontak sama persis','score'=>100]));}$needle=$this->n($name);Customer::query()->when($m->isNotEmpty(),fn($q)=>$q->whereNotIn('id',$m->keys()))->get(['id','name','address','branch_id'])->each(function($c)use($needle,$address,$m){similar_text($needle,$this->n($c->name),$p);if($p>=70)$m->put($c->id,['customer'=>$c,'reason'=>'Nama mirip ('.round($p).'%)'.(($address&&$c->address&&similar_text(strtolower($address),strtolower($c->address),$a)&&$a>=60)?', alamat juga mirip':''),'score'=>(int)$p]);});return $m->sortByDesc('score')->values();}private function n(string $x):string{return strtolower(preg_replace('/[^a-z0-9 ]/i','',trim($x)));}}
